LEGACY_NFL_DOC_PREFIXES = (
    "NFL_ACTIVE_ARCHITECTURE_", "NFL_PRODUCTION_V1_", "NFL_RESEARCH_V2_",
    "NFL_BETTING_ENGINE_", "NFL_EDGE_AUTHORITY_", "NFL_MODEL_AUTHORITY_",
    "README_NFL_", "SHA256_NFL_",
)


def cleanup_plan(repo_dir: str | Path = ".") -> list[str]:
    root=Path(repo_dir).resolve()
    candidates=[]
    for name in LEGACY_NFL_FILES:
        p=root/name
        if p.is_file() and p.name != Path(__file__).name:
            candidates.append(p.name)
    for p in root.iterdir():
        if not p.is_file():
            continue
        if p.name == Path(__file__).name:
            continue
        if any(p.name.startswith(pref) for pref in LEGACY_NFL_DOC_PREFIXES):
            candidates.append(p.name)
    cache=root / "__pycache__"
    if cache.is_dir():
        for p in cache.glob("nfl_*.pyc"):
            candidates.append(str(p.relative_to(root)))
    return sorted(set(candidates))


def cleanup_repository(repo_dir: str | Path = ".", *, apply: bool = False) -> dict:
    root=Path(repo_dir).resolve()
    plan=cleanup_plan(root)
    deleted=[]
    if apply:
        for name in plan:
            p=root/name
            if p.is_file():
                p.unlink()
                deleted.append(name)
    return {"repo":str(root),"apply":bool(apply),"candidates":plan,"deleted":deleted}


def _main():
    ap=argparse.ArgumentParser(description="NFL consolidated engine maintenance")
    ap.add_argument("--self-test", action="store_true")
    ap.add_argument("--cleanup-dry-run", action="store_true")
    ap.add_argument("--cleanup-apply", action="store_true")
    ap.add_argument("--repo", default=".")
    ap.add_argument("--print-ledger-sql", action="store_true")
    ns=ap.parse_args()
    if ns.self_test:
        print(json.dumps(preflight(), indent=2, sort_keys=True, default=str))
    if ns.cleanup_dry_run:
        print(json.dumps(cleanup_repository(ns.repo, apply=False), indent=2, sort_keys=True))
    if ns.cleanup_apply:
        print(json.dumps(cleanup_repository(ns.repo, apply=True), indent=2, sort_keys=True))
    if ns.print_ledger_sql:
        print(PRODUCTION_LEDGER_SQL)
    if not (ns.self_test or ns.cleanup_dry_run or ns.cleanup_apply or ns.print_ledger_sql):
        print(json.dumps({"source_tag":SOURCE_TAG,"components":len(_PAYLOADS)}, indent=2))


if __name__ == "__main__":
    _main()
